#include <stdio.h>

typedef struct {
    double x, y;
} Point;

double cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

Point sub(Point a, Point b) {
    Point r;
    r.x = a.x - b.x;
    r.y = a.y - b.y;
    return r;
}

double dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

int on_segment(Point p, Point a, Point b) {
    // Check if p is on segment ab, assuming cross product is 0
    return dot(sub(a, p), sub(b, p)) <= 1e-9;
}

int intersects(Point p0, Point p1, Point p2, Point p3) {
    Point d1 = sub(p1, p0);
    Point d2 = sub(p3, p2);

    double d = cross(d1, d2);

    double t1 = cross(sub(p2, p0), d2);
    double t2 = cross(sub(p2, p0), d1);

    if (d != 0) {
        double t = t1 / d;
        double u = t2 / d;
        if (t >= -1e-9 && t <= 1+1e-9 && u >= -1e-9 && u <= 1+1e-9)
            return 1;
        return 0;
    } else {
        // Parallel or collinear
        // Check if collinear
        if (cross(sub(p2, p0), d1) != 0) return 0;
        // Collinear: check overlap
        if (on_segment(p2, p0, p1)) return 1;
        if (on_segment(p3, p0, p1)) return 1;
        if (on_segment(p0, p2, p3)) return 1;
        if (on_segment(p1, p2, p3)) return 1;
        return 0;
    }
}

