struct Point {
    double x, y;
};

double cross(double ax, double ay, double bx, double by) {
    return ax * by - ay * bx;
}

double dot(double ax, double ay, double bx, double by) {
    return ax * bx + ay * by;
}

bool onSegment(Point p, Point a, Point b) {
    // Check if p is on segment ab, given p is collinear with a and b
    return min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

bool segmentsIntersect(Point p0, Point p1, Point p2, Point p3) {
    double d1x = p1.x - p0.x, d1y = p1.y - p0.y;
    double d2x = p3.x - p2.x, d2y = p3.y - p2.y;

    double d = cross(d1x, d1y, d2x, d2y);

    double t_num = cross(p2.x - p0.x, p2.y - p0.y, d2x, d2y);
    double s_num = cross(p2.x - p0.x, p2.y - p0.y, d1x, d1y);

    if (abs(d) < 1e-10) {
        // Parallel or collinear
        // Check collinear
        double c = cross(p2.x - p0.x, p2.y - p0.y, d1x, d1y);
        if (abs(c) > 1e-10) return false; // parallel, not collinear
        // Collinear: check overlap
        return onSegment(p2, p0, p1) || onSegment(p3, p0, p1) ||
               onSegment(p0, p2, p3) || onSegment(p1, p2, p3);
    }

    double t = t_num / d;
    double s = s_num / d;

    return t >= -1e-10 && t <= 1+1e-10 && s >= -1e-10 && s <= 1+1e-10;
}

