import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x) &&
               Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }

    static boolean intersects(Point p0, Point p1, Point p2, Point p3) {
        long d1 = cross(p0, p1, p2);
        long d2 = cross(p0, p1, p3);
        long d3 = cross(p2, p3, p0);
        long d4 = cross(p2, p3, p1);

        if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
            ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
            return true;
        }

        if (d1 == 0 && onSegment(p0, p1, p2)) return true;
        if (d2 == 0 && onSegment(p0, p1, p3)) return true;
        if (d3 == 0 && onSegment(p2, p3, p0)) return true;
        if (d4 == 0 && onSegment(p2, p3, p1)) return true;

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point p0 = new Point(fs.nextLong(), fs.nextLong());
        Point p1 = new Point(fs.nextLong(), fs.nextLong());
        Point p2 = new Point(fs.nextLong(), fs.nextLong());
        Point p3 = new Point(fs.nextLong(), fs.nextLong());

        System.out.println(intersects(p0, p1, p2, p3) ? 1 : 0);
    }
}
